function _r41_atlasPage(id){const raw=atlasPageR40(id),t=document.createElement('template');t.innerHTML=raw;const wrap=t.content.querySelector('.content-with-toc');if(!wrap)return raw;const profile=D.variants.some(x=>x.id===id)?id:state.variant;let tab=current.params.get('tab')||'tree';const tabs=[['tree','加点原图'],['choices','大节点选哪项'],['masters','大师配置'],['setup','地图与碑牌'],['play','操作与减配'],['source','来源记录']];if(!tabs.some(x=>x[0]===tab))tab='tree';const get=id=>wrap.querySelector('#'+id)?.outerHTML||'';let body=tab==='tree'?get('atlas-tree'):tab==='choices'?a41Body(profile,current.params.get('group')):tab==='masters'?get('atlas-masters'):tab==='setup'?get('atlas-setup'):tab==='play'?get('atlas-play')+get('atlas-budget'):get('atlas-source');if(tab==='tree')body=`<div class="a41-bridge"><b>亮点图只告诉你点哪里；多选大节点还要打开后选具体加成。</b>${routeLink('atlas/'+profile,'看这套目标下的大节点选择建议 →','btn primary',{tab:'choices'})}</div>`+body;const holder=document.createElement('div');holder.className='a41-workspace';holder.innerHTML=`<nav class="c41-tabs">${tabs.map(([v,l])=>routeLink('atlas/'+profile,l,'c41-tab '+(v===tab?'active':''),{tab:v})).join('')}</nav>`+body;wrap.replaceWith(holder);return t.innerHTML;}
function _r41_atlasStarter(){const raw=atlasStarterR40(),t=document.createElement('template');t.innerHTML=raw;const wrap=t.content.querySelector('.content-with-toc');if(!wrap)return raw;const tab=current.params.get('tab')||'route';const get=id=>wrap.querySelector('#'+id)?.outerHTML||'';const holder=document.createElement('div');holder.className='a41-workspace';holder.innerHTML=`<nav class="c41-tabs">${[['route','开荒推进'],['tree','分阶段原图'],['choices','大节点选哪项'],['rules','规则与转型']].map(([v,l])=>routeLink('atlas-starter',l,'c41-tab '+(v===tab?'active':''),{tab:v})).join('')}</nav>`+(tab==='tree'?`<div class="a41-bridge"><b>原图未展开选项，不能据此猜作者选择。</b>${routeLink('atlas-starter','查看大节点的补充选择建议','btn primary',{tab:'choices'})}</div>`+get('starter-tree'):tab==='choices'?a41Body(current.params.get('profile')||'starter',current.params.get('group')):tab==='rules'?get('starter-rules')+get('starter-next'):get('starter-route')+`<div class="actions">${routeLink('atlas-starter','下一步：看分阶段原图','btn',{tab:'tree'})}${routeLink('atlas-starter','大节点已经点亮？直接看选项','btn primary',{tab:'choices'})}</div>`);wrap.replaceWith(holder);return t.innerHTML;}
