// R42: one stage context and five coherent work areas. Source data are read-only.
const G42=D.guide42;
const R42StageIds=[...G42.campaign.map(c=>c.id),...D.stages.map(c=>c.id)];
state.context42=getStore('context42',state.stage);if(!R42StageIds.includes(state.context42))state.context42='e04';
function q42CP(){return G42.campaign.find(c=>c.id===state.context42)||null;}
function q42Context(extra={}){const p=q42CP()?{cp:state.context42}:{stage:state.stage};if(extra.stage)delete p.cp;if(extra.cp)delete p.stage;return {...p,...extra};}
function q42Link(r,label,cls='text-link',extra={}){return routeLink(r,label,cls,q42Context(extra));}
function q42Label(id){const c=G42.campaign.find(c=>c.id===id);return c?c.label+' · '+c.title:labelStage(D.stages.find(s=>s.id===id)||D.stages[0]);}
function q42Period(){const c=q42CP();return c?(c.number<4?'pre31':'post31'):'entry';}
function q42Text(x){return Array.isArray(x)?x.join('；'):String(x||'');}
function q42Rows(rows,headers){return `<div class="table-scroll"><table class="q42-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function q42Tabs(route,items,selected,extra={}){const key=extra._tabKey||'tab';extra={...extra};delete extra._tabKey;return `<nav class="q42-tabs" aria-label="本页阅读内容">${items.map(([id,t])=>q42Link(route,t,'q42-tab '+(id===selected?'active':''),{...extra,[key]:id})).join('')}</nav>`;}
function q42Steps(rows){return `<div class="q42-steps">${rows.map((r,i)=>`<article><span class="stepnum">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(Array.isArray(r)?r[0]:'第'+(i+1)+'步')}</h3><p>${esc(Array.isArray(r)?r[1]:r)}</p></div></article>`).join('')}</div>`;}
function q42Select(id,label,options,selected){return `<label class="q42-select" for="${id}"><span>${label}</span><select id="${id}" class="select">${options.map(([v,t])=>`<option value="${esc(v)}" ${selected===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function stageControl(){return `<div class="stage-control"><label for="r42-stage">当前阅读阶段</label><select id="r42-stage" aria-label="当前阅读阶段"><optgroup label="剧情 · 六个进度">${G42.campaign.map(c=>`<option value="${c.id}" ${state.context42===c.id?'selected':''}>${esc(c.label+' · '+c.title)}</option>`).join('')}</optgroup><optgroup label="异界 · 六份原件">${D.stages.map(c=>`<option value="${c.id}" ${state.context42===c.id?'selected':''}>${esc(labelStage(c))}</option>`).join('')}</optgroup></select></div>`;}
function footer(){return `<footer class="footer"><span>Fubgun 冰射 / 0.5.5 快照 · R42</span><div>${q42Link('coverage','来源边界与检查记录')}<span> · </span>${q42Link('tools/filters','原版过滤器')}</div></footer>`;}
function q42PhaseStrip(){const c=q42CP(),p=c?.original||branch().profile;return `<div class="q42-phase"><span class="tag ${state.context42==='e06'?'gold':''}">${c?'剧情配置':state.context42==='e06'?'原件只读':'异界配置'}</span><p>${esc(c?p.intro:p.overview)}</p>${q42Link('guide','本阶段任务 '+icon('arrow',12),'text-link')}</div>`;}
function q42Profile(c){const wanted=current.params.get('ref');return c.profiles.find(p=>p.id===wanted)||c.profiles.find(p=>p.id==='l3-24')||c.profiles[0];}
function q42CampaignBase(c,slot){const map={bow:'弓',body:'衣服',helmet:'头盔',gloves:'手套',boots:'鞋',quiver:'箭袋',amulet:'项链',belt:'腰带',ring1:'戒指Ⅰ',ring2:'戒指Ⅱ'};return q42Profile(c)?.rows.find(r=>r.category==='装备 · '+map[slot])||null;}
function q42CampaignTarget(c,slot,detail=false){const goal=G42.slotGoals[slot],b=q42CampaignBase(c,slot);if(!goal)return note('药剂、咒符、人物珠宝分别处理，不套普通装备词缀制作。');let base=b?.label||'使用当前可穿、实际效果更好的候选';if(base.includes('：'))base=base.split('：')[0]+' · 按实物选择';
 let body=`<div class="q42-target-head"><span class="tag">剧情功能目标 · 补充整理</span><h2>${esc(goal.title)}</h2><p>参考底材：<b>${esc(base)}</b>${b?.level?' · 裸底材需求'+b.level+'级':''}。这是比较示例，不是必须买齐的套装。</p></div>`;
 body+=q42Rows(goal.goals.map((t,i)=>[String(i+1),esc(t),i===0?'先保住':'按当前缺口比较']),['顺序','这件要具备什么','如何取舍']);body+=note(esc(goal.keep));
 if(detail)body+=c41Example(slot,true)+expand('底材、需求与原阶段依据',`<p>${esc(q42Profile(c)?.label||'')}</p><p>${b?esc('参考佩戴需求：'+wearText(b)+'；'+b.note):'以实际物品的需求栏为准。'}</p>${safeLink(c.source,'作者对应等级分支')}`);
 return body;
}
function q42TargetTable(compact=false){const c=q42CP();let rows=[];for(const slot of Object.keys(G42.slotGoals)){const gn=G42.slotGoals[slot];if(c){const b=q42CampaignBase(c,slot);const name=(b?.label||'当前可用候选').split('：')[0];rows.push([q42Link('item/'+slot,esc(gn.title),'q42-item-link'),`<strong>${esc(name)}</strong><small>${b?.level?'参考裸底材需求 '+b.level+'级':'以实物需求为准'}</small>`,`<div class="q42-mods">${gn.goals.map(t=>`<div>${esc(t)}</div>`).join('')}</div>`,q42Link('item/'+slot,'目标与做法 →','btn small')]);}else{const it=findItem(slot),t=targetData(slot);if(!it||!t)continue;const mods=[...t.raw,...t.definitions];rows.push([q42Link('item/'+slot,esc(gn.title),'q42-item-link'),`<strong>${esc(it.name)}</strong><small>${esc(it.wearShort||'需求按实物核对')}</small>${it.alternative?`<small class="q42-alternative">${esc(it.alternative)}</small>`:''}`,`<div class="q42-mods">${mods.length?mods.map(r=>`<div>${esc(r.text)}</div>`).join(''):'原件未写明完整数值；看单件目标的补充依据。'}</div>${t.supplement.length?`<details class="q42-inline"><summary>补位候选 ${t.supplement.length} 项</summary>${t.supplement.map(r=>`<p>${esc(r.text)}<small>${esc(r.kind)}</small></p>`).join('')}</details>`:''}`,q42Link('item/'+slot,state.context42==='e06'?'只读详情':'目标与做法 →','btn small')]);}}
 return `<div class="q42-targets">${q42Rows(rows,['部位','底材与使用条件','完整属性目标／补位方向','具体做法'])}</div>`+q42UtilityTargets();
}
function gear(){const c=q42CP();return heading('装备与打造 / 全身目标','先看这阶段的一整套','目标先列完整；哪件有缺口，就进入哪件的做法。不要求先录入现有装备。',true)+q42PhaseStrip()+(c?note('剧情目标是按原阶段装备方向整理的功能清单。底材只是有依据的比较示例，未提供的毕业数值不编造。'):note('表中保留作者快照的全部目标属性；高等级示例不是当前阶段的入场硬门槛。原件、补位候选与暗金定义在单件页区分。'))+q42TargetTable()+`<section class="q42-next"><h2>主装备之外，也要检查</h2><div class="q42-links">${q42Link('character','技能与实际操作','btn')}${q42Link('jewels','人物天赋珠宝','btn')}${q42Link('learn/readiness','药剂、咒符与出发检查','btn')}${q42Link('guide','接回本阶段任务','btn primary')}</div></section>`+footer();}
function q42CampaignSkills(c){return q42Rows(c.skills.map(s=>[`<strong>${esc(s.zh)}</strong><small>${esc(s.en)}</small>${s.optional?'<span class="tag gray">可选，非必须</span>':''}`,s.supports.length?s.supports.map((t,i)=>`<div class="q42-support">${i+1}. ${esc(t.zh)}${t.active?'（内嵌主动）':''}</div>`).join(''):'该阶段记录未配置辅助',`<p>${esc(s.note)}</p>${safeLink(s.url,'技能定义')}`]),['技能','当前阶段完整连接','什么时候加入／生效条件']);}
function q42CampaignGemList(c){const entries=new Map();function add(id,name,en,url,kind,where,opt){const x=entries.get(id)||{name,en,url,kind,qty:0,optional:0,where:[]};x.qty++;x.optional+=opt?1:0;x.where.push(where+(opt?'（可选配置）':''));entries.set(id,x)}for(const s of c.skills){add(s.id,s.zh,s.en,s.url,(c.reserve||[]).includes(s.key)?'精魂技能':'主动技能',s.zh,!!s.optional);for(const u of s.supports)add(u.key,u.zh,u.en,u.url,u.active?'内嵌主动':'辅助',s.zh,!!s.optional)}
 return note('下表是当前阶段完整连接所需副本数，包含标出的可选配置；不是刚进这个等级范围就必须一次凑齐，也不是换阶段重买全部。')+q42Rows([...entries.values()].map(x=>[`<strong>${esc(x.name)}</strong><small>${esc(x.en)}</small>`,esc(x.kind),String(x.qty)+(x.optional?`（其中可选${x.optional}）`:''),esc(x.where.join('、')),safeLink(x.url,'条目与需求')]),['名称／阶别','类别','数量','放在哪里','核对']);}
function q42SkillNames(id){const c=G42.campaign.find(c=>c.id===id);if(c)return c.skills.map(s=>({name:s.zh,links:s.supports.map(t=>t.zh)}));const b=D.branches.find(b=>'e0'+b.number===id);return b?b.skills.map(s=>({name:skillName(s.id),links:(s.support_skills||[]).map(t=>skillName(t.id))})):[];}
function q42Diff(a,b){if(!b)return '';const aa=q42SkillNames(a),bb=q42SkillNames(b),am=new Map(aa.map(s=>[s.name,s.links])),bm=new Map(bb.map(s=>[s.name,s.links]));const added=bb.filter(s=>!am.has(s.name)).map(s=>s.name),removed=aa.filter(s=>!bm.has(s.name)).map(s=>s.name),changed=bb.filter(s=>am.has(s.name)&&JSON.stringify(am.get(s.name))!==JSON.stringify(s.links));return `<div class="q42-diff"><h3>换阶段时，连接具体变了什么</h3><p><b>新增：</b>${esc(added.join('、')||'没有新技能')}</p><p><b>移出该快照：</b>${esc(removed.join('、')||'没有移除')}</p>${changed.length?q42Rows(changed.map(s=>[esc(s.name),esc(am.get(s.name).join(' ＋ ')||'无辅助'),esc(s.links.join(' ＋ ')||'无辅助')]),['同名技能','当前阶段连接','下一阶段连接']):'<p>其余同名技能的连接没有变化。</p>'}<small>这是资料之间的差异，不是无条件删技能指令。先具备新配置，再退出旧配置。</small></div>`;}
function q42Transition(){const c=q42CP(),index=R42StageIds.indexOf(state.context42),next=state.context42==='e05'||state.context42==='e06'?null:R42StageIds[index+1],rows=c?G42.milestones[c.id].gate:branch().profile.gate;return `<div class="q42-next"><h2>${next?'满足这些条件，再看下一阶段':'没有自动升级到06的路线'}</h2>${checksHtml(rows||G42.commonChecks,'r42-gate-'+state.context42,state.context42==='e06')}${next?q42Diff(state.context42,next)+`<div class="q42-links">${routeLink('guide','查看下一阶段：'+esc(q42Label(next)),'btn primary',next.startsWith('l')?{cp:next}:{stage:next})}${q42Link('troubleshoot','条件不齐，先定位问题','btn')}</div>`:note(state.context42==='e05'?'05后继续按实际缺口优化；06是有冲突的作者实装快照，仅供对照，不作为第六步采购目标。':'06只读，不提供执行或耗材验收。',true)}</div>`;}
function guide(){const c=q42CP(),m=c?G42.milestones[c.id]:null,b=branch(),active=['overview','skills','craft','next'].includes(current.params.get('tab'))?current.params.get('tab'):'overview';let h=heading('成长路线 / 当前阶段',c?c.title:b.profile.title,c?c.original.intro:b.profile.overview,true)+`<div class="q42-stage-index"><span>直接换阶段，不锁进度</span>${R42StageIds.map(id=>routeLink('guide',esc(id.startsWith('l')?G42.campaign.find(c=>c.id===id).label:labelStage(D.stages.find(s=>s.id===id)).split(' · ')[0]),'q42-stage-pill '+(state.context42===id?'active':''),id.startsWith('l')?{cp:id}:{stage:id})).join('')}</div>`+q42Tabs('guide',[['overview','本阶段目标'],['skills','技能与操作'],['craft','装备怎么做'],['next','准备与下一步']],active);
 if(active==='overview'){h+=`<div class="q42-focus"><span>先做这件事</span><strong>${esc(c?m.now:b.profile.goal)}</strong></div>`+q42TargetTable(true);h+=sec('q42-tasks','01','当前只做这些',q42Steps((c?c.original.tasks:b.profile.tasks).map((x,i)=>['任务 '+(i+1),x])),'',true)+`<div class="q42-links">${q42Link('guide','接着配技能 →','btn primary',{tab:'skills'})}${q42Link('guide','查看材料预留与转换条件','btn',{tab:'next'})}</div>`;}
 if(active==='skills'){h+=c?q42CampaignSkills(c):q42SkillSection();h+=sec('q42-play','02','清怪与首领怎么按',q42Steps(c?c.original.combat:b.profile.combat));h+=note(esc(c?c.original.mana:D.skillSetupNotes.sustain));h+=`<div class="q42-links">${q42Link('gems','按数量准备本阶段宝石','btn')}${q42Link('character','天赋、属性和资源检查','btn')}${q42Link('guide','技能就绪，接着看装备 →','btn primary',{tab:'craft'})}</div>`;}
 if(active==='craft'){h+=`<div class="q42-focus"><span>本阶段什么时候值得做</span><strong>${esc(c?m.craft:b.profile.ssf)}</strong><p>${esc(c?m.stop:b.profile.cannot)}</p></div>`;h+=q42Rows(Object.entries(G42.slotGoals).map(([slot,g])=>[q42Link('item/'+slot,esc(g.title)),esc(C41.examples[c41Key(slot)]?.next||g.keep),q42Link('item/'+slot,'看目标 → 按状态做','btn small',{tab:'craft'})]),['哪一件','先保住什么／补哪条','具体步骤']);h+=`<div class="q42-links">${q42Link('supplies','材料与底材从哪里来','btn')}${q42Link('guide','换装完成，检查下一步 →','btn primary',{tab:'next'})}</div>`;}
 if(active==='next'){h+=`<div class="q42-focus"><span>下一阶段前先预留</span><strong>${esc(c?m.keep:b.profile.nextNote)}</strong></div>`;h+=`<div class="q42-links">${q42Link('learn/permanent','任务永久奖励','btn')}${q42Link('learn/ascendancy','升华点与试炼','btn')}${q42Link('learn/readiness','属性、精魂和药剂验收','btn')}${!c||c.id==='l06'?q42Link('atlas-starter','第一张地图怎么开始','btn'):''}</div>`+q42Transition();}
 h+=expand('当前内容依据',c?`<p>${esc(c.original.sourceNote)}${c.fallback?' 本页沿用已核对42–59配置，不冒充60+独立原件。':''}</p>${safeLink(c.source,'作者对应等级分支')}<p>已保存原详稿：${esc(c.referenceFile)}。参考底材和判断案例属于补充整理；不改原构筑。</p>`:`<p>原件：${esc(b.sourceFile)}；SHA-256 ${esc(b.sha256)}</p>${safeLink(D.skillSetupNotes.source,'作者异界正文')}`);return h+footer();}
function q42SkillSection(){const t=document.createElement('template');t.innerHTML=characterR39();return t.content.querySelector('#char-skills')?.innerHTML||'';}
function q42CharacterSection(id){const t=document.createElement('template');t.innerHTML=characterR39();return t.content.querySelector('#'+id)?.innerHTML||'';}
function character(){const c=q42CP(),tab=['skills','play','tree','check'].includes(current.params.get('tab'))?current.params.get('tab'):'skills';let h=heading('人物配置 / '+(c?'剧情':'异界'),'连法、操作、天赋，分开看','人物天赋不是异界天赋；人物珠宝不是技能／辅助宝石。',true)+q42PhaseStrip()+q42Tabs('character',[['skills','技能连接'],['play','清怪与首领'],['tree','天赋与升华'],['check','属性与资源检查']],tab);
 if(tab==='skills')h+=(c?q42CampaignSkills(c):q42SkillSection()+expand('辅助孔位、品质与升级安排',q42CharacterSection('char-upgrade')))+`<div class="q42-links">${q42Link('gems','完整宝石数量与阶段变化','btn')}${q42Link('special-gems','血脉辅助，不是人物珠宝','btn')}${q42Link('character','接着看操作 →','btn primary',{tab:'play'})}</div>`;
 if(tab==='play')h+=q42Steps(c?c.original.combat:branch().profile.combat)+note(esc(c?c.original.mana:D.skillSetupNotes.sustain))+`<div class="q42-links">${q42Link('character','检查天赋与升华','btn',{tab:'tree'})}${q42Link('guide','回到本阶段任务','btn')}</div>`;
 if(tab==='tree'){if(c)h+=`<div class="q42-focus"><span>当前属性点怎么选</span><strong>先满足正在使用的装备与技能需求；没有缺口时以敏捷为默认方向。</strong><p>${esc(c.original.tree)}</p></div>${safeLink(c.source,'打开作者对应阶段树')}<div class="q42-links">${q42Link('learn/ascendancy','四次升华：各拿2点','btn')}${q42Link('jewels','人物天赋里的珠宝','btn')}</div>`;else h+=q42CharacterSection('char-tree')+expand('原件节点完整记录（不是逐级点序）',q42Rows(branch().nodes.map(n=>[String(n.row),esc(n.zh),esc(n.scope),esc(n.status),`<code>${esc(n.id)}</code>`]),['原件序号','节点','武器组范围','来源状态','内部ID']));}
 if(tab==='check')h+=q42ResourceCheck()+`<div class="q42-links">${q42Link('learn/build-use','原件如何导入与装配','btn')}${q42Link('learn/skill-check','技能不生效，逐项排查','btn')}${q42Link('guide','接着检查换阶段条件','btn primary',{tab:'next'})}</div>`;
 return h+footer();}
function q42ResourceCheck(){const c=q42CP();let h=note('此页不会扫描角色。先在游戏内配置好辅助和装备，再读人物属性及最终预留；参考值不是入场门槛。');if(c){const p=q42Profile(c);h+=expand('本阶段已保存的完整需求参考',q42Select('q42-ref','参考配置',c.profiles.map(p=>[p.id,p.label]),p.id)+q42Rows(p.rows.map(r=>[esc(r.label),esc(r.category),String(r.str),String(r.dex),String(r.int),esc(r.note)]),['对象','类别','力量','敏捷','智慧','依据／条件'])+`<p>${esc(p.kind)}</p>`);}
 h+=`<form id="q42-resource" class="q42-resource"><h2>核对实际精魂余量</h2><p>输入游戏显示的总精魂与全部常驻的最终精魂预留合计；生命预留另算，不混在精魂里。</p><div class="q42-form-row"><label>实际总精魂<input name="total" type="number" min="0" step="any" inputmode="decimal" required></label><label>最终精魂预留合计<input name="used" type="number" min="0" step="any" inputmode="decimal" required></label><button class="btn" type="submit">核对余量</button></div><p id="q42-resource-result" role="status">尚未输入实际值，不判断是否够用。</p></form>`+checksHtml(G42.commonChecks,'r42-resource-'+state.context42,state.context42==='e06');return h;}

function c41Params(extra={}){return {...Object.fromEntries(current.params||[]),...q42Context(),period:q42Period(),...extra};}
function c41Link(label,extra={},cls='btn'){const slot=current.section==='early-craft'?(current.params.get('slot')||'bow'):(current.slot||'bow');return routeLink('item/'+slot,label,cls,c41Params({tab:'craft',...extra}));}
function c41EssenceChoices(slot,params,kind){const key=c41Key(slot),all=Object.values(c41Catalog()).filter(e=>e.effect?.[key]),groups=[...new Set(all.map(e=>c41GoalOf(e.id)))];const goal=groups.includes(params.get('goal'))?params.get('goal'):null;let html=`<section class="q42-purpose"><h3>这次只补哪一条？</h3><p>先选缺口，再比较手中材料。没有对应精华，保留蓝装或选择下方的富豪分支；不要求三档都用。</p>${q42Select('c41-goal','本次缺口',[['','请选择，不自动决定'],...groups.map(g=>[g,C41Goals[g]||g])],goal||'')}</section>`;if(!goal)return html;
 const es=all.filter(e=>c41GoalOf(e.id)===goal).sort((a,b)=>({lesser:0,normal:1,greater:2}[a.tier]??2)-({lesser:0,normal:1,greater:2}[b.tier]??2));return html+`<div class="q42-essences">${es.map(e=>`<article><header><span>${esc(({lesser:'次级',normal:'普通',greater:'强效'})[e.tier]||'专用')}</span><h4>${esc(e.zh)}</h4></header><p class="q42-effect">${esc(e.effect[key])}</p><p>${esc(c41TierUse(e))}</p><small>${esc(c41Limit(e,slot))}</small><div>${c41Link('我有这颗，核对使用步骤',{kind,action:'essence',essence:e.id,goal},'btn small')}</div></article>`).join('')}</div>`;}
function c41Generic(slot,params){const p=new URLSearchParams(params);p.set('period',q42Period());const t=document.createElement('template');t.innerHTML=_r41_c41Generic(slot,p);const c=q42CP(),action=p.get('action');const intro=t.content.querySelector('.c41-intro');if(intro){if(action)intro.remove();else{const x=C41.examples[c41Key(slot)];intro.innerHTML=`<b>${esc(c&&slot==='bow'?G42.milestones[c.id].craft:x?.next||'先确认物品类别，不套普通装备流程。')}</b><small>${c?'剧情过渡：只在备用候选上处理当前缺口，改善够用就停。':'普通过渡件：先比较实际收益，不把它当作者高配配方。'}</small>`;}}if(action)t.content.querySelector('.c41-example')?.remove();for(const a of t.content.querySelectorAll('a'))if(a.textContent.includes('收尾说明（异界快照')){a.setAttribute('href',path('item/'+slot,q42Context({tab:'finish'})));a.textContent='按当前阶段，查看品质与镶嵌';}return t.innerHTML;}
function q42Finish(slot){const c=q42CP(),p=D.finish[c?c.id:state.stage]?.[slot];if(!p)return note('此部位没有独立收尾资料，不复制别件的品质或孔位规则。',true);if(state.context42==='e06')return note('06仅阅读原件与冲突，不给品质、镶嵌或耗材操作。请主动选择01–05的可执行路线。',true)+expand('原件已有说明，仅作对照',`<p>${esc(p.why)}</p><p>${esc(p.special||'')}</p>`);let h=`<div class="q42-focus"><span>决定保留以后才做</span><strong>${esc(p.pick)}</strong><p>${esc(p.why)}</p></div>`;h+=q42Rows([[esc(p.qualityTool||'不使用普通品质材料'),esc(p.quality)],[esc(p.cap?'只补缺少的孔':'普通增幅孔不适用'),esc(p.socket)]],['材料／状态','这个部位的规则']);h+=q42Steps(p.steps.map((x,i)=>['收尾 '+(i+1),c?x.replace('开始一张低投入图验证','在当前可稳定完成的剧情内容中比较'):x]));h+=checksHtml([...p.checks,...G42.commonChecks],'r42-finish-'+state.context42+'-'+slot,state.context42==='e06');h+=expand('没有首选材料与不能做的操作',[...(p.alternatives||[]),...(p.avoid||[])].map(x=>`<p>${esc(x)}</p>`).join(''));h+=`<div class="q42-links">${q42Link('guide','回本阶段，检查下一步','btn primary',{tab:'next'})}${q42Link('supplies','查询品质、孔位与强化材料','btn',{tab:'finish'})}</div>`;return h;}
function itemPage(slot,params){if(!D.slots.some(s=>s.id===slot))return heading('装备与打造','未找到这个部位')+q42Link('gear','返回全身装备目标','btn');const c=q42CP(),name=D.slots.find(x=>x.id===slot).name;let tab=params.get('tab')||'target';if(['plan','steps'].includes(tab))tab='craft';if(!['target','craft','finish'].includes(tab))tab='target';const onlyMain=c&&!(slot in G42.slotGoals);let h=heading('装备与打造 / '+esc(q42Label(state.context42)),name,c?'先看本阶段可用目标，不把异界高阶底材当剧情入场要求。':'完整属性与来源保留；普通补装和作者专用工艺分开。',true)+`<div class="q42-links q42-itemnav">${q42Link('gear','← 全身目标')}${q42Select('q42-slot','换一件看',D.slots.map(s=>[s.id,s.name]),slot)}</div>`+q42Tabs('item/'+slot,[['target','装备目标'],['craft','一步步做'],['finish','换上前检查']],tab);
 if(c){if(tab==='target'){h+=onlyMain?note(slot==='jewels'?'人物珠宝先看实际已分配的孔；剧情没有逐孔实装记录，不在这里编固定采购数量。':'本阶段没有此栏位的独立作者装备实装。先核对实际药剂／咒符槽或武器组，不照搬后期。')+q42Link(slot==='jewels'?'jewels':'learn/readiness','查看对应使用说明','btn'):q42CampaignTarget(c,slot,true);h+=`<div class="q42-links">${q42Link('item/'+slot,'目标确认，看怎么做 →','btn primary',{tab:'craft'})}</div>`;}else if(tab==='craft'){h+=onlyMain?note('此类不是普通九类装备打造。不要套用精华升黄流程。')+q42Finish(slot):c41Generic(slot,params);}else h+=q42Finish(slot);}
 else{if(tab==='target')h+=fullTargetPanel(findItem(slot),slot)+targetContext(findItem(slot),slot);else if(tab==='craft')h+=c41CraftBody(slot,params);else h+=q42Finish(slot);}
 return h+footer();}
function earlyCraft(){if(state.context42==='e06')return heading('06 · 只读限制','这份快照不提供制作步骤','请主动选择01–05或剧情阶段；不会因为进入普通工作台就解除只读。',true)+footer();const slot=G42.slotGoals[current.params.get('slot')]?current.params.get('slot'):'bow';return heading('装备与打造','从手中这件开始','阶段、部位、物品状态保留在地址中；换路线会清除不适用的材料。',true)+q42PhaseStrip()+q42Select('q42-craft-slot','装备部位',Object.entries(G42.slotGoals).map(([k,v])=>[k,v.title]),slot)+note('先看目标，再决定补哪条。已经有好蓝装或黄装，无需从白装重做。')+`<div class="q42-links">${q42Link('item/'+slot,'先看本阶段这件的完整目标','btn')}${q42Link('item/'+slot,'进入逐步打造','btn primary',{tab:'craft',kind:current.params.get('kind')||'unknown'})}</div>`+c41Generic(slot,current.params)+footer();}
function craftTiming(){const slot=G42.slotGoals[current.params.get('slot')]?current.params.get('slot'):'bow';return heading('装备与打造','不是颜色更高就值得换','先比较这件保住的关键属性，再看一次加工能否补上缺口。',true)+q42PhaseStrip()+q42Select('q42-example-slot','比较哪件',Object.entries(G42.slotGoals).map(([k,v])=>[k,v.title]),slot)+(q42CP()?q42CampaignTarget(q42CP(),slot):c41Example(slot,true))+`<div class="q42-links">${q42Link('item/'+slot,'对照目标，进入当前状态步骤','btn primary',{tab:'craft'})}${q42Link('supplies','没有合适材料怎么办','btn')}</div>`+footer();}
