function jewelsPage(){if(!q42CP())return _r41_jewelsPage();return heading('人物配置 / 天赋树','剧情珠宝：先有实际孔，再选物品','这里是人物天赋里的珠宝，不是技能辅助、装备符文或异界配置。',true)+q42PhaseStrip()+note('剧情原件没有逐孔珠宝实装。不要照着异界2孔／3孔示例，假定当前人物已经点到同样孔位。')+q42Steps([['先看实际天赋树','确认已分配人物珠宝槽。尚无孔就先沿当前加点推进，不为一颗差珠宝硬绕远。'],['已有孔再补短板','普通珠宝比较对当前攻击有效的属性；尚未转暴击，不把暴击词缀当默认最优。刷图击杀回蓝不代替无小怪时的恢复。'],['特殊珠宝等实物与范围','泉井之心看自身词缀；抗衡黑暗还要看范围内对应已分配天赋。同名不保证实际效果相同。']])+`<div class="q42-links">${routeLink('jewels','查看01已保存珠宝目标与数量依据','btn',{stage:'e01'})}${q42Link('special-jewels','特殊人物珠宝定义','btn')}${q42Link('character','回到人物天赋说明','btn primary',{tab:'tree'})}</div>`+footer();}
