function learningPage(id){if(id==='start')return guide();if(id==='readiness')return heading('人物配置 / 换装后检查','出发之前，逐项确认','这里合并实际资源核对和完整出发清单，不要求你从旧资料拼接。',true)+q42PhaseStrip()+q42ResourceCheck()+q42LearningBody(id)+footer();if(id==='ascendancy')return ascendancyChinese();const q=D.learningPages[id]||D.learningPages.audit;return heading('说明 / '+esc(q.title),esc(q.title),esc(q.description||q.summary),true)+q42PhaseStrip()+q42LearningBody(q.id)+`<div class="q42-links">${q42Link('guide','回到本阶段任务','btn primary')}${q42Link('troubleshoot','仍有问题，按症状排查','btn')}</div>`+footer();}
function q42LearningBody(id){const q=D.learningPages[id]||D.learningPages.audit,sections=q.sections||[];let i=Number(current.params.get('part')||0);if(!Number.isInteger(i)||i<0||i>=sections.length)i=0;const s=sections[i],dest=current.section==='supplies'?'supplies':'learn/'+q.id,pp=current.section==='supplies'?{tab:'get'}:{};return `<div class="q42-reader"><nav class="q42-chapters" aria-label="阅读章节">${sections.map((s,j)=>q42Link(dest,`${String(j+1).padStart(2,'0')} ${esc(s.title)}`,j===i?'active':'',{...pp,part:j})).join('')}</nav><article class="q42-article"><h2>${esc(s?.title||'说明')}</h2>${s?.html||''}${s?.sources?.length?learnedSources(s.sources):''}<div class="q42-next">${i? q42Link(dest,'← 上一节','btn',{...pp,part:i-1}):''}${i<sections.length-1?q42Link(dest,'下一节 →','btn primary',{...pp,part:i+1}):q42Link('guide','本专题读完，回阶段任务','btn primary')}</div></article></div>`;}
function supplies(){const tab=['get','reserve','finish'].includes(current.params.get('tab'))?current.params.get('tab'):'get',c=q42CP();let h=heading('装备与打造 / 获取与预留','缺什么，就找对应获取方式','买成品、留现用品、做备用件是不同选择；没有实时价格，不承诺打造一定更便宜。',true)+q42PhaseStrip()+q42Tabs('supplies',[['get','装备与材料获取'],['reserve','这个阶段留什么'],['finish','品质与镶嵌查询']],tab);if(tab==='get')h+=q42LearningBody('acquisition');if(tab==='reserve')h+=`<div class="q42-focus"><span>先留给下一阶段</span><strong>${esc(c?G42.milestones[c.id].keep:branch().profile.nextNote)}</strong></div>`+q42Transition()+note('原版过滤器可能隐藏部分低价值材料或底材。这里只解释原规则，不为获取需求修改原文件。')+q42Link('tools/filters','选择保存的原版过滤器','btn');if(tab==='finish')h+=q42Rows(D.slots.filter(s=>s.group==='main').map(s=>[esc(s.name),esc(D.finish[state.context42]?.[s.id]?.qualityTool||'不套用普通品质材料'),esc(D.finish[state.context42]?.[s.id]?.socket||''),q42Link('item/'+s.id,'本部位完整收尾','btn small',{tab:'finish'})]),['部位','品质材料','增幅孔规则','实际步骤'])+`<div class="q42-links">${q42Link('tools/dictionary','查询具体符文、灵核、催化剂的作用','btn')}${q42Link('reference','完整强化材料与条件','btn',{doc:'runes-all.html'})}</div>`;return h+footer();}
function troubleshoot(){const cases=[['damage','打不动','先检查当前技能连法与实际生效，再比较武器。不要默认所有问题都该用崇高解决。',[['character','技能连法与实际操作',{tab:'skills'}],['learn/skill-check','辅助、武器组与生效条件',{}],['item/bow','弓的目标和比较方法',{tab:'target'}]]],['survival','容易死','先核对换下旧装后的生命抗性、药剂咒符、地图词缀。回到可稳定完成的内容再比较。',[['learn/readiness','出发前完整检查',{}],['item/life_flask','药剂条件与收尾',{tab:'finish'}],['learn/map-run','当前地图的风险',{}]]],['mana','缺蓝／常驻开不全','按游戏内最终消耗与预留检查；击杀回蓝不解决无小怪阶段。',[['character','实际精魂与属性检查',{tab:'check'}],['learn/skill-check','资源和技能失效排查',{}],['jewels','人物珠宝与回蓝边界',{}]]],['materials','材料不够','能用就先用；没有合适精华不强迫购买，也不把低阶全部合成。',[['supplies','材料获取和本阶段预留',{tab:'reserve'}],['item/bow','从现有物品状态开始',{tab:'craft'}],['tools/filters','原版过滤器到底显示什么',{}]]],['swap','换装／转型后更弱','先保留并退回可用旧配置；逐项核对新技能、属性、武器组和整套配套，不只看一件新装备。',[['guide','对照下一阶段真正的差异',{tab:'next'}],['character','武器组与资源核对',{tab:'check'}],['learn/build-use','导入和装配检查',{}]]]];const id=current.params.get('case')||'damage',v=cases.find(x=>x[0]===id)||cases[0];return heading('成长路线 / 故障排查','先定位问题，再花材料','每条排查都回到当前阶段，不跳到高配采购单。',true)+q42PhaseStrip()+q42Tabs('troubleshoot',cases.map(x=>[x[0],x[1]]),v[0],{_tabKey:'case'})+`<div class="q42-focus"><span>${esc(v[1])}</span><strong>${esc(v[2])}</strong></div>`+q42Steps(v[3].map(([r,n,p],i)=>['检查 '+(i+1),n]))+`<div class="q42-links">${v[3].map(([r,n,p])=>q42Link(r,esc(n),'btn',p)).join('')}</div>`+footer();}

