function archive(file,label='查看完整资料'){const f=String(file).split(/[?#]/)[0].split('/').pop(),m=f.match(/^([le]0[1-6])\.html$/);if(m)return routeLink('guide',label,'text-link',m[1][0]==='l'?{cp:m[1]}:{stage:m[1]});if(Q42FileMap[f]){const [r,p]=Q42FileMap[f];return q42Link(r,label,'text-link',p);}return q42Link('reference',label,'text-link',{doc:f});}
function referencePage(params){const f=params.get('doc')||'beginner-guide.html',d=D.documents.find(d=>d.file===f),r=window.R42references?.[f];if(!d)return heading('查询与下载','没有这个资料条目')+q42Link('tools','返回资料目录','btn');if(!r){q42LoadRefs();return heading('查询与下载 / 资料阅读',esc(d.title),'正在读取包内资料，不请求外部网站。')+'<div id="q42-reference-loading" role="status">正在加载本地正文……</div>'+footer();}let i=Number(params.get('part')??r.anchorMap?.[params.get('anchor')]??0);if(!Number.isInteger(i)||i<0||i>=r.sections.length)i=0;return heading('查询与下载 / 原详稿正文',esc(r.title),'正文已放入统一阅读页；历史工具的交互功能保留在原档案，不能把静态摘录当原计算器。')+`<div class="q42-reader"><nav class="q42-chapters" aria-label="资料章节">${r.sections.map((s,j)=>q42Link('reference',String(j+1).padStart(2,'0')+' '+esc(s.title),i===j?'active':'',{doc:f,part:j})).join('')}</nav><article class="q42-article q42-reference"><h2>${esc(r.sections[i]?.title||r.title)}</h2>${r.sections[i]?.html||'<p>没有可提取的独立正文；请打开原档案。</p>'}<div class="q42-next">${i>0?q42Link('reference','← 上一节','btn',{doc:f,part:i-1}):''}${i<r.sections.length-1?q42Link('reference','下一节 →','btn primary',{doc:f,part:i+1}):''}</div></article></div>`+expand('原档案与边界',`<p>本页重排原文，不改原文件；旧版配色、工具表单及版本提示仍保留在原件。原件SHA-256：<code>${esc(r.sha256)}</code>。</p><a class="btn" href="${esc(r.path)}" target="_blank" rel="noopener">打开历史原文件／交互工具</a>`)+footer();}
let q42RefsLoading=false;
function q42LoadRefs(){if(q42RefsLoading||window.R42references)return;q42RefsLoading=true;const s=document.createElement('script');s.src=G42.referenceAsset;s.onload=()=>{q42RefsLoading=false;if(current.section==='reference')render();};s.onerror=()=>{q42RefsLoading=false;const el=$('#q42-reference-loading');if(el){el.textContent='本地正文资源未读到。请完整解压整包，保留assets文件夹，不要只复制index.html。';}};document.head.appendChild(s);}
function toolIndex(){const groups=[['按问题查询',[['tools/dictionary','材料、符文与催化剂','按名字和实际部位作用找，不把查询表当操作连招。'],['filter-guide','原版颜色与声音','逐条显示匹配条件与动作，不重新配色。'],['filter-check','为什么看不到物品','输入物品条件查看原版匹配顺序。']]],['原件与可追溯资料',[['tools/builds','六份人物原件','编号与哈希保留；06仍只读。'],['tools/filters','四份原版过滤器','当前只推荐保存的四个原版，不修改显示隐藏。'],['tools/sources','来源、版本与未核实项','作者快照与补充建议分开。']]]];return heading('查询与下载','查资料，不用再找旧版本','日常流程已放回阶段和部位；这里保留查询、原件和可追溯的深入资料。')+groups.map(([n,ls])=>`<section class="q42-library-group"><h2>${n}</h2><div class="q42-tool-grid">${ls.map(([r,t,d])=>`<article><h3>${q42Link(r,t)}</h3><p>${d}</p>${q42Link(r,'进入 →','btn small')}</article>`).join('')}</div></section>`).join('')+sec('r42-documents','03','全部深入资料',documentCatalog())+expand('导出／恢复网页中的手动勾选记录',backupPanel())+footer();}
