const G45=window.FUBGUN_GUIDE45;
const old45={card:r43Card,jewels:r43Jewels,jewelCard:r43JewelCard,gear, itemPage,guide,search:searchData,atlas:atlasPage,
 targetTable:q42TargetTable,utilities:q42UtilityTargets,skillSection:q42SkillSection,transition:q42Transition,tools,render,coverage};
function e45(s){return esc(cn44(s));}
function r45Guide(b,uid){return G45.guides[b.stage]?.[uid]||null;}
function r45Wear(base){const f=base.fact,w=f||base.wear;if(!w)return '按实物核对；没有固定需求记录';return [w.level!==null&&w.level!==undefined?'等级 '+w.level:'',w.str?'力量 '+w.str:'',w.dex?'敏捷 '+w.dex:'',w.int?'智慧 '+w.int:''].filter(Boolean).join(' / ');}
function r45Sources(url=G45.source,label='作者正文与选择依据'){return `<span class="r45-source">${safeLink(url,label)}</span>`;}
function r45BaseTable(g){if(!g.bases.length)return '';return `<section id="r45-bases-${g.uid}" class="r45-base-detail"><h3>可用底材与过渡选择</h3><p>不是按名称依次购买。先看你当前能穿的成品；下表为普通未加工底材，生成词缀后的最终需求以实物为准。</p>${q42Rows(g.bases.map(x=>[
 `<b>${e45(x.name)}</b><small>${x.later?'后续候选，不是当前门槛':'本阶段可比较'} · ${e45(x.kind)}</small>`,
 e45(r45Wear(x)),
 x.fact?`${e45(x.fact.base)}${x.fact.note?`<small>${e45(x.fact.note)}</small>`:''}`:'没有新增基础数值；按实际物品核对',
 e45(x.why)+r45Sources(x.url||G45.source,x.fact?'底材数据':'方向依据')
 ]),['底材与适用范围','裸底材佩戴','基础／固有效果','为什么比较'])}</section>`;}
function r45Supplement(g){return g.supplement.length?`<div class="r45-option-list"><h3>剩余属性怎么取舍</h3><p>下面是按缺口挑选的候选，不要求同时占满，也不把描述行数当作合法前后缀数量。</p>${g.supplement.map(x=>`<p><b>${e45(x.text)}</b><small>${e45(x.kind)} · ${e45(x.detail)}</small></p>`).join('')}</div>`:'';}
function r45Example(g){const x=g.example;if(!x)return '';return `<div class="r45-example"><h3>比较例子：${e45(x.title)}</h3><p>${e45(x.example)}</p><p class="r45-caution">${e45(x.caution)}</p><small>教学示例，不是作者面板、你的角色或保证收益。</small></div>`;}
function r45LongGuide(g,b){if(g.readonly)return `<div class="r45-caution">作者实装只读：原面板、字段差异与绑定状态保留，不提供普通底材采购或可执行加工路线。</div>`;return `${r45BaseTable(g)}<section class="r45-decision"><h3>先保住什么</h3><p>${e45(g.keep)}</p>${r45Supplement(g)}<h3>什么时候换／什么时候值得做</h3><p>${e45(g.when)}</p><h3>怎样取得，不必从白装开始</h3><p>${e45(g.acquire)}</p><h3>白底和成品怎么比较</h3><p>${e45(g.compare)}</p><p class="r45-caution">${e45(G45.compareRule)} 旧导出的固定数值及旧品质情景只在证据层保留，不再充当当前成品面板。</p>${r45Example(g)}<p class="r45-stop"><b>做到这里先停：</b>${e45(g.stop)}</p>${r45Sources()}</section>`;}
function r45Unique(it){const u=G45.unique[it.name];if(!u)return '';const arrows=it.name==="Cadiro's Gambit"?`<div class="r45-arrows"><h3>六种随机箭分别做什么</h3><p>每支箭只得到其中一种；不把六种加成同时计入，也不推定它们等概率。这里解释物品引用的效果，不改原面板。</p>${q42Rows(G45.arrows.map(a=>[`<b>${e45(a.name)}</b>`,e45(a.effect),safeLink(a.url,'效果依据')]),['箭矢','作用及边界','出处'])}</div>`:'';return `<section class="r45-mechanic" data-r45-unique="${esc(it.name)}"><h3>这件暗金的用法与替代</h3><p><b>${e45(u.brief)}</b></p><p>${e45(u.why)}</p>${arrows}<p><b>未取得时：</b>${e45(u.get)}</p><p><b>换上前：</b>${e45(u.check)}</p>${r45Sources(u.url,'物品机制依据')}</section>`;}
function r45Utility(it,b){if(R43_MAIN.includes(it.uid))return '';const life=it.uid==='life_flask',mana=it.uid==='mana_flask',charm=it.uid.startsWith('charm');let p='';if(life)p='生命药剂先比较当前能用阶别、实际回复量、速度与即时回复；不要把短期过渡药剂强制做满品质。';else if(mana)p='魔力药剂按连续消耗与无小怪场景检验，不只看单次回复总量；已有好用普通药剂可继续用。';else if(charm)p='先确认对应咒符槽开放。核对触发条件、防护内容、当前充能与持续时间；短时防护不是永久免疫。';else if(it.uid==='weapon2')p='第二武器组不是另一套必购全身装备；只读原配置，共用栏位不要重复采购。';return p?`<div class="r45-utility-tip"><b>怎么判断这件：</b>${e45(p)}</div>`:'';}
r43Card=function(it,b,isolated=false){const t=document.createElement('template');t.innerHTML=old45.card(it,b,isolated);const article=t.content.querySelector('article.r43-equip');if(!article)return t.innerHTML;const g=r45Guide(b,it.uid);const header=article.querySelector('header');
 if(g){const intro=document.createElement('section');intro.className='r45-pick';intro.dataset.r45Guide=it.uid;const current=g.bases.filter(x=>x.current);intro.innerHTML=`<div class="r45-minihead">${it.source_is_unique?'普通替代与配装方向':'底材与过渡 · 先看这里'}</div><p>${e45(g.brief)}</p>${current.length?`<p class="r45-base-line"><b>可比较：</b>${current.map(x=>`<span>${e45(x.name)}${x.fact?`<small>（裸底材${x.fact.level}级）</small>`:''}</span>`).join('、')}</p>`:''}`;header.after(intro);
 const deep=document.createElement('details');deep.className='r45-details';deep.id='r45-guide-'+it.uid;deep.open=isolated;deep.innerHTML=`<summary>底材需求、替代、词缀取舍与打造时机</summary><div class="r45-detail-body">${r45LongGuide(g,b)}</div>`;article.querySelector('.r43-proof')?.before(deep);
 if(!g.readonly){const tip=document.createElement('p');tip.className='r45-stop r45-card-stop';tip.innerHTML='<b>够用就先停：</b>'+e45(g.stop);deep.after(tip);}
 }
 const marker=document.createElement('h3');marker.className='r45-panel-label';marker.textContent='作者配置 · 当前采集面板';const target=article.querySelector('.r43-stats,.r43-mods,.r43-missing');if(target)target.before(marker);
 const unique=r45Unique(it);if(unique){const d=document.createElement('details');d.className='r45-details r45-unique-details';d.open=isolated;d.innerHTML='<summary>这件暗金的效果、用法与替代</summary>'+unique;article.querySelector('.r43-proof')?.before(d);}
 const util=r45Utility(it,b);if(util){const u=document.createElement('div');u.innerHTML=util;header.after(u.firstElementChild);}
 return r44HTML(t.innerHTML);};
function r45JewelPreparation(b,specialOnly=false,compact=false){const ro=b.stage==='e06';let keys=specialOnly?['well','darkness']:['mana','ordinary','well','darkness'];const body=keys.map(k=>{const j=G45.jewels[k];return `<article class="r45-jewel-guide" id="r45-jewel-${k}"><h3>${e45(j.title)}</h3><p>${e45(j.body)}</p><p><b>取得：</b>${e45(j.get)}</p><p><b>暂时没有：</b>${e45(j.fallback)}</p><p><b>使用检查：</b>${e45(j.check)}</p>${r45Sources(j.url,'作者正文／物品依据')}${j.acquireUrl?r45Sources(j.acquireUrl,'特殊遗物来源'):''}</article>`;}).join('');return `<section class="r45-jewel-prep" id="r45-jewel-prep"><div class="r45-sectionhead"><h2>人物珠宝怎么准备、怎么替换</h2><span>指导 ≠ 已镶嵌清单</span></div><p>${ro?'作者实装的珠宝仍有孔位生效冲突；下列为通用阅读解释，不解除只读。':b.jewels.length?'上方是作者当前配置，下面说明没有配齐时怎样选择；新增珠宝在现有有效孔位内替换，不额外增加孔位。':'当前采集确实没有配置具体珠宝，但仍能按作者正文准备回蓝或输出珠宝；不因此虚构作者已插的物品。'}</p>${compact?`<div class="r45-jewel-brief"><p><b>前期：</b>先比较一颗有击杀回蓝词缀的蓝玉或合适普通输出珠宝；没有击杀时的供蓝单独处理。</p><p><b>后期：</b>泉井之心看自身词缀；抗衡黑暗看实物半径和已分配的对应节点，两者各有限定数量。</p>${q42Link('jewels','查看取得、替代与范围判断 →','text-link',{focus:'r45-jewel-prep'})}</div>`:`<div class="r45-jewel-guide-grid">${body}</div><p class="r45-caution">本页不以旧导出孔数安排固定采购数量。当前绑定记录与完整连通验证是两回事；实际装入和启用仍核对游戏内人物树。</p>`}</section>`;}
