q42TargetTable=function(compact=false){const b=r43Build();if(!b)return old45.targetTable(compact);const rows=R43_MAIN.map(uid=>{const it=b.equipment.find(x=>x.uid===uid);if(!it)return null;const g=r45Guide(b,uid);return [q42Link('item/'+uid,e45(D.slots.find(s=>s.id===uid)?.name||uid),'q42-item-link',{tab:'target'}),`<strong>${e45(it.name)}</strong><small>当前采集面板；括号为范围</small>${g?`<p>${e45(g.brief)}</p>`:''}`,`${it.panel.top_stats.length?`<div class="r45-inline-stats">${it.panel.top_stats.map(x=>`${e45(R43_STAT[x.label]||x.label)}：${e45(x.value)}`).join('；')}</div>`:''}${it.panel.modifiers.length?r43Panel(it.panel):'<p>面板未给完整词缀；不从旧保存值补算。</p>'}${it.sourcePanelCaution?.length?`<p class="r45-caution">${it.sourcePanelCaution.map(e45).join('；')}</p>`:''}`,q42Link('item/'+uid,'完整面板、底材与做法 →','btn small',{tab:'target'})];}).filter(Boolean);return `<section class="q42-targets r45-current-targets"><p class="r45-source-note">与装备总览使用同一份当前采集数据。旧导出示例只在单件证据中保留，不再混称“当前目标”。</p>${q42Rows(rows,['部位','当前配置与过渡方向','当前完整面板','阅读入口'])}</section>`+q42UtilityTargets();};
