function r45RestoreOps(html,id){if(id!=='expedition')return html;const t=document.createElement('template');t.innerHTML=html;let replaced=new Set();const w=document.createTreeWalker(t.content,NodeFilter.SHOW_TEXT);let n;const nodes=[];while(n=w.nextNode())if(n.parentElement&&!n.parentElement.closest('[data-r44-original],pre,script,style,.r43-rawparagraph'))nodes.push(n);
 for(const x of nodes){let s=x.textContent;for(const [a,b] of r45Unknown){const re=new RegExp(escRE44(a),'gi');if(re.test(s)){re.lastIndex=0;s=s.replace(re,b);replaced.add(a);}}s=s.replace(/作者未展开说明的特殊符文\s*符文/g,'作者未展开说明的特殊符文').replace(/SS＝/g,'最高优先＝').replace(/S＝/g,'第二优先＝').replace(/A＝/g,'第三优先＝').replace(/B＝/g,'第四优先＝').replace(/C＝/g,'第五优先＝').replace(/B 档/g,'第四档');x.textContent=s;}
 if(replaced.size){const note=document.createElement('section');note.className='r45-source-ops';note.innerHTML='<p><b>规则保留，个别专名单独待核。</b>下方操作来自已保存的作者攻略；“首领传闻①”等是阅读编号，不冒称国服正式名称。历史价值数字不作当前市场价格或收益保证。</p><details class="r43-proof"><summary>未核专名的原文对应（只用于查原页）</summary><div data-r44-original>'+r45Unknown.filter(([a])=>replaced.has(a)).map(([a,b])=>'<p>'+esc(b)+'：'+esc(a)+'</p>').join('')+'</div></details>';const tabs=t.content.querySelector('.c41-tabs,.r30-tabs,.q42-tabs');if(tabs)tabs.after(note);else t.content.prepend(note);}
 return t.innerHTML;}
