let searchIndex45=null;
function makeSearch45(){const out=[];for(const b of C43.builds){for(const g of Object.values(G45.guides[b.stage]||{})){if(g.readonly)continue;for(const x of g.bases)out.push({title:cn44(x.name),text:cn44(b.name)+' · '+g.title+' · '+(x.later?'后续候选':'当前可比较底材'),query:cn44(x.why+' '+(x.fact?.base||''))+' '+x.en,route:'item/'+g.uid,params:{stage:b.stage,tab:'target',focus:'r45-guide-'+g.uid}});out.push({title:g.title+'的替代、取舍与打造时机',text:cn44(b.name),query:cn44(g.brief+' '+g.keep+' '+g.when+' '+g.acquire+' '+g.stop),route:'item/'+g.uid,params:{stage:b.stage,tab:'target',focus:'r45-guide-'+g.uid}});}
 for(const [id,j]of Object.entries(G45.jewels))out.push({title:j.title,text:cn44(b.name)+' · 珠宝准备与使用',query:j.body+' '+j.get+' '+j.fallback+' '+j.check,route:'jewels',params:{stage:b.stage,focus:'r45-jewel-'+id}});
 for(const it of b.equipment){const u=G45.unique[it.name];if(u)out.push({title:u.zh+'的效果与替代',text:cn44(b.name),query:u.brief+' '+u.why+' '+u.get+' '+u.check+(it.name==="Cadiro's Gambit"?' '+G45.arrows.map(a=>a.name+' '+a.effect).join(' '):''),route:'item/'+it.uid,params:{stage:b.stage,tab:'target'}});}}
 return out;}
searchData=function(q){if(!searchIndex45)searchIndex45=makeSearch45();const words=String(q||'').toLowerCase().trim().split(/\s+/).filter(Boolean);const found=words.length?searchIndex45.filter(x=>words.every(w=>(x.title+' '+x.text+' '+x.query).toLowerCase().includes(w))):[];found.sort((a,b)=>(b.params?.stage===state.stage)-(a.params?.stage===state.stage));return [...found,...old45.search(q)].filter((x,i,a)=>a.findIndex(y=>y.title===x.title&&y.route===x.route&&JSON.stringify(y.params)===JSON.stringify(x.params))===i).slice(0,24);};
render=function(){const r=old45.render();const focus=current.params.get('focus');if(focus&&/^r45-[a-z0-9-]+$/.test(focus)){const el=document.getElementById(focus);if(el){let p=el;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement;}el.classList.add('r45-focus');requestAnimationFrame(()=>el.scrollIntoView({block:'start'}));}}
 document.title='冰霜射击攻略 · R45';document.querySelectorAll('.side-bottom,.sidebar .version,.sidebar .sidebar-version').forEach(e=>{e.textContent='0.5.5 · R45 配装指导修复';});document.documentElement.dataset.r45Ready='true';return r;};
